		this.dfa = dfa;
		this.refOnly = ignoreNonRefTypeFlow;

		this.infoFlowGraph = new MemoryEfficientGraph<EquivalentValue>();
		this.returnRef = new ParameterRef(g.getBody().getMethod().getReturnType(), -1); // it's a dummy parameter ref

