	protected List handleInvokeExpr(InvokeExpr ie, FlowSet fs)
	{
		// get the data flow graph
		MutableDirectedGraph dataFlowGraph = dfa.getInvokeDataFlowGraph(ie); // must return a graph whose nodes are Refs!!!
