							dataFlowGraph.addNode(sinkEqVal);
						if(!dataFlowGraph.containsNode(sourceEqVal))
							dataFlowGraph.addNode(sourceEqVal);
						dataFlowGraph.addEdge(sourceEqVal, sinkEqVal);
						if(printMessages)
